def transform(grid):
    import numpy as np
    g = np.array(grid)
    out = g.copy()
    points = np.argwhere(g == 8)
    lo, hi = points.min(0), points.max(0)
    base = g[lo[0]:hi[0]+1, lo[1]:hi[1]+1] == 8
    variants, seen = [], set()
    for mirrored in (False, True):
        for k in range(4):
            mask = np.rot90(base, k)
            if mirrored:
                mask = np.fliplr(mask)
            key = (mask.shape, mask.tobytes())
            if key not in seen:
                seen.add(key)
                variants.append((mask, mirrored))

    # candidate placements: every template cell must be colour 3
    candidates = {}
    H, W = g.shape
    for mask, mirrored in variants:
        h, w = mask.shape
        offsets = [(int(y), int(x)) for y, x in np.argwhere(mask)]
        for y in range(H-h+1):
            for x in range(W-w+1):
                cells = tuple(sorted((y+dy, x+dx) for dy, dx in offsets))
                if all(g[p] == 3 for p in cells):
                    if cells not in candidates or not mirrored:
                        candidates[cells] = mirrored
    cells = sorted(candidates)
    n = len(cells)
    occupied = [set(c) for c in cells]
    conflicts = [sum(1 << j for j in range(n) if occupied[i] & occupied[j])
                 for i in range(n)]
    memo = {}

    def pack(mask):
        if not mask:
            return (0, 0), {0}
        if mask in memo:
            return memo[mask]
        i = next(j for j in range(n) if mask & (1 << j))
        bit = 1 << i
        no_score, no_sets = pack(mask & ~bit)
        sub_score, sub_sets = pack(mask & ~conflicts[i])
        yes_score = (sub_score[0]+1, sub_score[1]-int(candidates[cells[i]]))
        yes_sets = {s | bit for s in sub_sets}
        if yes_score > no_score:
            result = yes_score, yes_sets
        elif yes_score < no_score:
            result = no_score, no_sets
        else:
            result = yes_score, yes_sets | no_sets
        memo[mask] = result
        return result

    # maximise number of disjoint copies; ties prefer unreflected copies
    score, solutions = pack((1 << n)-1)
    outcomes = set()
    for solution in solutions:
        union = set()
        for i in range(n):
            if solution & (1 << i):
                union.update(cells[i])
        outcomes.add(tuple(sorted(union)))
    assert len(outcomes) == 1, 'Equally ranked non-overlapping matches give different output grids'
    chosen = min(solutions)
    for i in range(n):
        if chosen & (1 << i):
            for y, x in cells[i]:
                out[y, x] = 8
            orientation = 'mirrored and rotated' if candidates[cells[i]] else 'rotated'
            emit(out, f'Recolor this complete {orientation} template occurrence (all cells green) to 8; it is disjoint from the other selected copies.')
    emit(out, f'Completed {score[0]} non-overlapping template copies, using {-score[1]} reflected copies where needed.')
    return out
